//! Persistent instance profiles, isolated from the GUI and from Minecraft's installed files.
//! The only writable instance paths are derived from UUIDs generated by this module.
use std::{
    fs, io,
    path::{Path, PathBuf},
    time::{Duration, SystemTime, UNIX_EPOCH},
};

use serde::{Deserialize, Serialize};
#[cfg(windows)]
use std::os::windows::fs::MetadataExt;
use uuid::Uuid;

use crate::instance::{GameTarget, Instance, validate_name};

#[derive(Clone)]
pub struct InstanceStore {
    root: PathBuf,
}

#[derive(Serialize, Deserialize)]
struct Profile {
    id: Uuid,
    name: String,
    created_at_ms: u64,
    target: GameTarget,
}

impl Profile {
    fn from_instance(instance: &Instance) -> io::Result<Self> {
        let created_at_ms = instance
            .created_at()
            .duration_since(UNIX_EPOCH)
            .map_err(io::Error::other)?
            .as_millis()
            .try_into()
            .map_err(|_| io::Error::other("Timestamp overflow"))?;
        Ok(Self {
            id: instance.id(),
            name: instance.name().into(),
            created_at_ms,
            target: instance.target().clone(),
        })
    }

    fn into_instance(self) -> io::Result<Instance> {
        if self.target.minecraft_version.trim().is_empty() {
            return Err(invalid("Minecraft version is missing"));
        }
        let created = UNIX_EPOCH
            .checked_add(Duration::from_millis(self.created_at_ms))
            .ok_or_else(|| invalid("Invalid creation time"))?;
        Instance::new(self.id, &self.name, self.target, created)
            .map_err(|_| invalid("Invalid instance profile"))
    }
}

fn invalid(message: &str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message)
}

fn guard_directory(path: &Path) -> io::Result<()> {
    let info = fs::symlink_metadata(path)?;
    if !info.file_type().is_dir() || info.file_type().is_symlink() {
        return Err(invalid("Instance directory is not an ordinary directory"));
    }
    #[cfg(windows)]
    if info.file_attributes() & 0x400 != 0 {
        // FILE_ATTRIBUTE_REPARSE_POINT: junctions, mount points
        return Err(invalid("Reparse point is not an instance directory"));
    }
    Ok(())
}

impl InstanceStore {
    pub fn new(root: PathBuf) -> Self {
        Self { root }
    }

    pub fn default_path() -> io::Result<PathBuf> {
        directories::ProjectDirs::from("", "Cinder", "Cinder Launcher")
            .map(|dirs| dirs.data_dir().join("instances"))
            .ok_or_else(|| {
                io::Error::new(io::ErrorKind::NotFound, "Cannot locate application data")
            })
    }

    fn ensure_root(&self) -> io::Result<()> {
        fs::create_dir_all(&self.root)?;
        guard_directory(&self.root)
    }

    pub fn game_dir(&self, id: Uuid) -> PathBuf {
        self.root.join(id.to_string()).join("game")
    }

    fn directory(&self, id: Uuid) -> PathBuf {
        self.root.join(id.to_string())
    }

    fn read(&self, id: Uuid) -> io::Result<Instance> {
        let dir = self.directory(id);
        guard_directory(&dir)?;
        let path = dir.join("profile.json");
        let meta = fs::symlink_metadata(&path)?;
        if !meta.file_type().is_file() || meta.file_type().is_symlink() {
            return Err(invalid("Invalid profile file"));
        }
        let profile: Profile = serde_json::from_slice(&fs::read(path)?)
            .map_err(|err| io::Error::new(io::ErrorKind::InvalidData, err))?;
        if profile.id != id {
            return Err(invalid("Profile ID does not match directory"));
        }
        profile.into_instance()
    }

    pub fn list(&self) -> io::Result<Vec<Instance>> {
        self.ensure_root()?;
        let mut result = Vec::new();
        for entry in fs::read_dir(&self.root)? {
            let entry = entry?;
            let name = entry.file_name().to_string_lossy().into_owned();
            // An interrupted new-instance transaction never becomes visible.
            let Ok(id) = Uuid::parse_str(&name) else {
                continue;
            };
            if id.to_string() != name {
                continue;
            }
            result.push(self.read(id)?);
        }
        result.sort_by_key(|item| (item.created_at(), item.id()));
        Ok(result)
    }

    pub fn create(&self, name: &str, target: GameTarget) -> io::Result<Instance> {
        self.create_with_id(Uuid::new_v4(), name, target)
    }

    fn create_with_id(&self, id: Uuid, name: &str, target: GameTarget) -> io::Result<Instance> {
        validate_name(name)
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid name"))?;
        if target.minecraft_version.trim().is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "Minecraft version is missing",
            ));
        }
        self.ensure_root()?;
        let destination = self.directory(id);
        if fs::symlink_metadata(&destination).is_ok() {
            return Err(io::Error::new(
                io::ErrorKind::AlreadyExists,
                "Duplicate instance ID",
            ));
        }
        let instance = Instance::new(id, name, target, SystemTime::now())
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid instance"))?;
        let staged = tempfile::Builder::new()
            .prefix(".new-")
            .tempdir_in(&self.root)?;
        let game = staged.path().join("game");
        for part in ["mods", "config", "saves"] {
            fs::create_dir_all(game.join(part))?;
        }
        let file = staged.path().join("profile.json");
        let mut bytes = fs::File::create(&file)?;
        serde_json::to_writer_pretty(&mut bytes, &Profile::from_instance(&instance)?)?;
        bytes.sync_all()?;
        // Windows cannot rename the staging directory while a child file handle is open.
        drop(bytes);
        // Publish only after the complete private directory has been written.
        fs::rename(staged.path(), destination)?;
        Ok(instance)
    }

    pub fn rename(&self, id: Uuid, name: &str) -> io::Result<Instance> {
        self.ensure_root()?;
        validate_name(name)
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "Invalid name"))?;
        let mut instance = self.read(id)?;
        instance.rename(name).map_err(|_| invalid("Invalid name"))?;
        let dir = self.directory(id);
        let mut temporary = tempfile::NamedTempFile::new_in(&dir)?;
        serde_json::to_writer_pretty(&mut temporary, &Profile::from_instance(&instance)?)?;
        temporary.as_file().sync_all()?;
        // Same-directory atomic replacement, including on Windows (MoveFileExW).
        temporary
            .persist(dir.join("profile.json"))
            .map_err(|error| error.error)?;
        Ok(instance)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::instance::Loader;

    fn target() -> GameTarget {
        GameTarget {
            minecraft_version: "1.21.1".into(),
            loader: Loader::NeoForge { version: None },
        }
    }

    #[test]
    fn p1_01_02_create_list_and_restart() {
        let temp = tempfile::tempdir().unwrap();
        let store = InstanceStore::new(temp.path().join("instances"));
        let a = store.create("パック A", target()).unwrap();
        assert_eq!(store.list().unwrap().len(), 1);
        let reopened = InstanceStore::new(temp.path().join("instances"));
        let entry = reopened.list().unwrap().pop().unwrap();
        assert_eq!(entry.id(), a.id());
        assert_eq!(entry.name(), "パック A");
        assert_eq!(entry.target(), a.target());
        assert_eq!(entry.launch_state(), &crate::instance::LaunchState::Stopped);
        assert_eq!(
            entry.install_state(),
            &crate::instance::InstallState::NotInstalled
        );
    }

    #[test]
    fn p1_04_rename_preserves_id_and_world() {
        let temp = tempfile::tempdir().unwrap();
        let store = InstanceStore::new(temp.path().join("instances"));
        let a = store.create("A", target()).unwrap();
        let world = store.game_dir(a.id()).join("saves/world.txt");
        fs::write(&world, b"precious world").unwrap();
        let changed = store.rename(a.id(), "変更後").unwrap();
        assert_eq!(changed.id(), a.id());
        assert_eq!(
            changed.created_at(),
            a.created_at()
                .checked_sub(Duration::from_nanos(
                    a.created_at()
                        .duration_since(UNIX_EPOCH)
                        .unwrap()
                        .subsec_nanos() as u64
                        % 1_000_000
                ))
                .unwrap()
        );
        assert_eq!(fs::read(&world).unwrap(), b"precious world");
        assert_eq!(store.list().unwrap()[0].name(), "変更後");
    }

    #[test]
    fn p1_05_06_07_08_distinct_worlds_mods_and_config() {
        let temp = tempfile::tempdir().unwrap();
        let store = InstanceStore::new(temp.path().join("instances"));
        let a = store.create("A", target()).unwrap();
        let b = store.create("A", target()).unwrap();
        for folder in ["mods", "config", "saves"] {
            fs::write(store.game_dir(a.id()).join(folder).join("same.dat"), b"A").unwrap();
            fs::write(store.game_dir(b.id()).join(folder).join("same.dat"), b"B").unwrap();
            fs::remove_file(store.game_dir(a.id()).join(folder).join("same.dat")).unwrap();
            assert_eq!(
                fs::read(store.game_dir(b.id()).join(folder).join("same.dat")).unwrap(),
                b"B"
            );
        }
        assert_ne!(a.id(), b.id());
    }

    #[test]
    fn p1_09_incomplete_and_malformed_profile_not_published() {
        let temp = tempfile::tempdir().unwrap();
        let store = InstanceStore::new(temp.path().join("instances"));
        let a = store.create("A", target()).unwrap();
        fs::create_dir(store.root.join(".new-aborted")).unwrap();
        assert_eq!(store.list().unwrap().len(), 1);
        fs::write(
            store.directory(a.id()).join("profile.json"),
            b"invalid JSON",
        )
        .unwrap();
        assert_eq!(
            store.list().err().unwrap().kind(),
            io::ErrorKind::InvalidData
        );
    }

    #[test]
    fn invalid_input_has_no_side_effects() {
        let temp = tempfile::tempdir().unwrap();
        let store = InstanceStore::new(temp.path().join("instances"));
        assert!(store.create("   ", target()).is_err());
        assert!(!store.root.exists());
        let a = store.create("Valid", target()).unwrap();
        assert!(store.rename(a.id(), "\n").is_err());
        assert_eq!(store.list().unwrap()[0].name(), "Valid");
        assert!(store.rename(Uuid::new_v4(), "X").is_err());
    }

    #[cfg(unix)]
    #[test]
    fn p1_13_symlink_root_does_not_modify_external() {
        use std::os::unix::fs::symlink;
        let temp = tempfile::tempdir().unwrap();
        let actual = temp.path().join("external");
        fs::create_dir(&actual).unwrap();
        let trusted = InstanceStore::new(actual.clone());
        let a = trusted.create("A", target()).unwrap();
        let alias = temp.path().join("alias");
        symlink(&actual, &alias).unwrap();
        let untrusted = InstanceStore::new(alias);
        assert!(untrusted.rename(a.id(), "Changed").is_err());
        assert!(untrusted.create("B", target()).is_err());
        assert_eq!(trusted.list().unwrap()[0].name(), "A");
    }

    #[test]
    fn duplicate_id_refused_without_touching_existing_world() {
        let temp = tempfile::tempdir().unwrap();
        let store = InstanceStore::new(temp.path().join("instances"));
        let id = Uuid::new_v4();
        let a = store.create_with_id(id, "A", target()).unwrap();
        let world = store.game_dir(a.id()).join("saves/world.txt");
        fs::write(&world, b"keep").unwrap();
        assert_eq!(
            store
                .create_with_id(id, "B", target())
                .err()
                .unwrap()
                .kind(),
            io::ErrorKind::AlreadyExists
        );
        assert_eq!(fs::read(world).unwrap(), b"keep");
        assert_eq!(store.list().unwrap()[0].name(), "A");
    }

    #[test]
    fn p1_03_failed_create_does_not_change_existing_instance() {
        let temp = tempfile::tempdir().unwrap();
        let data = temp.path().join("instances");
        let store = InstanceStore::new(data.clone());
        let a = store.create("A", target()).unwrap();
        let profile = data.join(a.id().to_string()).join("profile.json");
        let before = fs::read(&profile).unwrap();
        let bad = InstanceStore::new(temp.path().join("not-a-directory"));
        fs::write(temp.path().join("not-a-directory"), b"blocked").unwrap();
        assert!(bad.create("B", target()).is_err());
        assert_eq!(fs::read(&profile).unwrap(), before);
        assert_eq!(store.list().unwrap().len(), 1);
    }

    #[cfg(windows)]
    #[test]
    fn p1_13_windows_junction_root_rejected() {
        use std::process::Command;
        let tmp = tempfile::tempdir().unwrap();
        let actual = tmp.path().join("real");
        fs::create_dir(&actual).unwrap();
        let trusted = InstanceStore::new(actual.clone());
        let a = trusted.create("A", target()).unwrap();
        let junction = tmp.path().join("link");
        let out = Command::new("cmd")
            .arg("/C")
            .arg("mklink")
            .arg("/J")
            .arg(&junction)
            .arg(&actual)
            .output()
            .unwrap();
        assert!(
            out.status.success(),
            "could not create Windows junction: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let untrusted = InstanceStore::new(junction);
        assert!(untrusted.rename(a.id(), "Changed").is_err());
        assert!(untrusted.create("B", target()).is_err());
        assert_eq!(trusted.list().unwrap()[0].name(), "A");
    }

    #[cfg(windows)]
    #[test]
    fn p1_16_windows_locked_profile_preserves_prior_name() {
        use std::os::windows::fs::OpenOptionsExt;
        let tmp = tempfile::tempdir().unwrap();
        let store = InstanceStore::new(tmp.path().join("instances"));
        let a = store.create("A", target()).unwrap();
        let profile = store.directory(a.id()).join("profile.json");
        let locked = fs::OpenOptions::new()
            .read(true)
            .share_mode(0)
            .open(&profile)
            .unwrap();
        assert!(store.rename(a.id(), "B").is_err());
        drop(locked);
        assert_eq!(store.list().unwrap()[0].name(), "A");
    }

    #[cfg(unix)]
    #[test]
    fn p1_13_symlink_profile_rejected() {
        use std::os::unix::fs::symlink;
        let temp = tempfile::tempdir().unwrap();
        let store = InstanceStore::new(temp.path().join("instances"));
        let a = store.create("A", target()).unwrap();
        let external = temp.path().join("outside");
        fs::write(&external, b"outside").unwrap();
        let profile = store.directory(a.id()).join("profile.json");
        fs::remove_file(&profile).unwrap();
        symlink(&external, &profile).unwrap();
        assert!(store.rename(a.id(), "B").is_err());
        assert_eq!(fs::read(&external).unwrap(), b"outside");
    }
}
